/**
 * Given a list of detected tags, find the best matching short module.
 * Returns the module ID with the most tag matches, or null if no match.
 */
export function findBestShortModule(detectedTags: string[]): string | null {
  const scores: Record<string, number> = {};
  for (const tag of detectedTags) {
    const moduleId = SHORT_MODULE_TAG_MAP[tag];
    if (moduleId) {
      scores[moduleId] = (scores[moduleId] || 0) + 1;
    }
  }
  let best: string | null = null;
  let bestScore = 0;
  for (const [moduleId, score] of Object.entries(scores)) {
    if (score > bestScore) {
      best = moduleId;
      bestScore = score;
    }
  }
  return best;
}
